window.SHOWCASE={works:[{slug:"campus-badge",title:"校园文创徽章",level:"简单",type:"文创",hours:2,tag:"简单 · 2 课时",image:"/media/campus-badge.jpg",alt:"3D 打印完成的三枚校园文创徽章，旁边放着游标卡尺与 60mm 设计草图",copy:"把社团标志做成一套可替换文字的胸牌，练文字凸起、边缘圆角和薄板厚度，一节课内能拿到实物。",meta:"建模重点：基本体 / 文字 / 壁厚",dims:"60 × 60 × 3.2 mm",material:"PLA 哑光白",weight:"约 8 g",modelTime:"45 分钟",printTime:"约 35 分钟",background:"社团纳新要做一批胸牌，亚克力开模单价高、改字要重新做版。学生提出的替代方案是：底板统一开一次，文字部分按社团单独出件，坏一个补一个。任务因此从“画个好看的图案”变成了“设计一套可替换、可复制、成本可控的小件”。",goal:"理解二维轮廓怎样通过厚度、圆角和文字成为可打印薄板，并能解释为什么文字笔画不能太细。",constraints:["外形控制在 60 mm 以内，给别针底座留出 12 mm 安装区","文字最小笔画不小于 0.8 mm，否则 0.4 mm 喷嘴两次走线会粘连","底板厚度不低于 2.4 mm，低于此值别针受力会沿层间开裂","单件打印不超过 40 分钟，保证一节 45 分钟的课能完整出件"],skills:["草图约束","文字拉伸","倒角","首层附着"],steps:["画 60 × 60 外轮廓，标注圆角 R6，完全约束后再进入下一步","文字转成草图并拉伸 0.6 mm，检查最小笔画与字间距","底板拉伸 2.4 mm，四边加 0.4 mm × 45° 倒角改善首层","在背面留 1.6 mm 深别针槽，槽底加 1 mm 圆角分散应力","导出 STL 前检查法线方向与单位，切片预览确认无悬空"],settingsRows:[["层高","0.2 mm","兼顾文字清晰度与出件时间，0.28 mm 时笔画会糊"],["墙线","2 圈","薄板主要靠墙线承力，1 圈会在别针处开裂"],["填充","15% 网格","薄件几乎不受填充影响，过高的填充只增加时间"],["底板附着","无裙边 / 平台胶","第一层面积大，翘边主要来自平台不洁"],["摆放方向","文字面朝上","朝下会被平台纹理压平，浮雕感消失"]],failures:["文字笔画糊在一起：笔画小于 0.8 mm 或层高设为 0.28 mm","四角翘起：平台有油污，或首层被压得过薄","别针槽开裂：槽底是直角，应力集中；应加圆角并加厚到 2.8 mm"],iterations:[{round:"第 1 版",issue:"文字笔画 0.6 mm，出件后“启”字下半部分粘连不可读",change:"笔画统一到 0.9 mm，字间距从 0.3 mm 加到 0.6 mm",evidence:"同角度翻拍对比，30 cm 处可辨认"},{round:"第 2 版",issue:"别针插入 6 次后槽底出现白痕",change:"槽底加 R1 圆角，底板 2.4 → 2.8 mm",evidence:"插拔 20 次无裂纹"}],tests:[{item:"文字可读性",method:"30 cm 距离目视 + 手机翻拍",target:"全部文字可辨认",actual:"四款社团字样全部可读"},{item:"别针插拔",method:"同一件连续插拔",target:"20 次不裂",actual:"20 次后仅轻微磨痕"},{item:"跌落",method:"1 m 高度自由落体到瓷砖",target:"3 次不碎",actual:"3 次边角轻微崩边"},{item:"单件耗时",method:"切片预估 + 实际打印",target:"≤ 40 分钟",actual:"35 分钟"}],defend:[{q:"为什么文字不做成凹刻？",a:"凹刻在 0.2 mm 层高下边缘容易积料，深色耗材里反而看不清；凸起还能在翻模时保留形状。"},{q:"如果社团标志有三个颜色怎么办？",a:"底板与文字分开出件再装配，或用换色分层（在第 12 层换料），课堂阶段建议先做单色验证结构。"},{q:"这个件最可能先坏在哪里？",a:"别针槽底。它是应力集中点，所以第 2 版加了圆角并把底板加厚到 2.8 mm。"}],transfer:["班牌与图书角标识","实验室器材标签","校园活动纪念章系列"],course:{slug:"junior-3d-foundation",title:"3D 建模与打印基础"},articles:[{slug:"block-modeling-for-students",title:"积木式建模：让初中生先组合，再谈参数"},{slug:"first-print-then-create",title:"先出件再创造：为什么第一课不从软件界面开始"}]},{slug:"phone-stand",title:"手机支架",level:"普通",type:"功能",hours:3,tag:"普通 · 3 课时",image:"/media/phone-stand.jpg",alt:"3D 打印手机支架实体、结构草图与卡尺",copy:"从看网课时的真实角度出发，测量手机尺寸、算倾角、加加强肋，打印后按测试结果改第二版。",meta:"建模重点：尺寸 / 受力 / 迭代",dims:"92 × 78 × 105 mm",material:"PLA 或 PETG",weight:"约 62 g",modelTime:"90 分钟",printTime:"约 2 小时",background:"学生在教室用手机看操作视频，手机靠在书堆上反复滑倒。第一版作品只解决了“能立住”，第二版才开始处理“带壳能用、插着充电线也能用、横竖屏都能放”这些真实条件。",goal:"把使用者、尺寸边界和稳定性指标写成一个可测试的小项目，并用测试数据决定改哪里。",constraints:["适配 71–78 mm 宽的手机（含常见保护壳）","倾角控制在 60°–70°，低于 55° 时看视频要低头","底座进深不超过 90 mm，不能占掉键盘前缘","背面留 14 × 9 mm 充电线穿孔，插线时不顶住插头","单件打印不超过 2.5 小时，保证一节课能完成主体"],skills:["尺寸测量","角度约束","加强肋","公差配合"],steps:["用卡尺测量手机厚度、宽度和充电口位置，记录带壳与不带壳两组数据","建立底座、后靠背与挡边三段结构，先锁死倾角 65°","在靠背背面加两条 3 mm 加强肋，方向与受力一致","挡边前倾 5°，高度 12 mm，避免遮挡屏幕下沿","导出后先打印 1:2 缩小件验证比例，再出全尺寸件"],settingsRows:[["层高","0.2 mm","外观面可见层纹，0.16 mm 更细腻但时间增加约 25%"],["墙线","3 圈","承力靠墙线，2 圈在挡边根部会先裂"],["填充","20% 立方","立方填充抗压比网格好，成本差别很小"],["支撑","仅接触面","加强肋下方需要支撑，接触面支撑好拆"],["摆放方向","底面朝下","层向与主要受力方向垂直，避免层间剥离"]],failures:["一放手机就后仰：底座进深不足 70 mm，重心落在支撑面外","挡边挡住屏幕：挡边过高或没有前倾角","插线时整机被顶起：充电孔位置按裸机测量，未留壳体厚度"],iterations:[{round:"第 1 版",issue:"底座 70 mm 进深，放上带壳手机后向后翻倒",change:"底座加到 92 mm，后靠背下移 8 mm 降低重心",evidence:"侧向 5 N 推力位移 < 2 mm"},{round:"第 2 版",issue:"充电线插头把手机顶起 3 mm",change:"穿孔从 9 mm 加高到 14 mm，孔底做 2 mm 圆角",evidence:"三种常见插头均可插入且不顶机"}],tests:[{item:"倾角",method:"量角器测量靠背面与桌面夹角",target:"60°–70°",actual:"65°"},{item:"侧向稳定性",method:"弹簧秤水平推顶端 5 N",target:"位移 < 2 mm",actual:"1.2 mm"},{item:"横竖屏切换",method:"两种姿态各放置 10 次",target:"不滑落",actual:"10/10 稳定"},{item:"打印耗时",method:"切片预估 + 实际",target:"≤ 2.5 小时",actual:"2 小时 5 分"}],defend:[{q:"为什么不用更省料的三角支撑？",a:"三角支撑省料但占进深，桌面空间不够；我们用背面双肋把弯矩分散到两条腿上。"},{q:"PLA 和 PETG 你会怎么选？",a:"教室环境选 PLA 就够；如果夏天车内或窗边使用，PETG 耐温更好但要注意拉丝。"},{q:"如果手机更宽怎么办？",a:"挡边内侧留了 2 mm 余量，超过 78 mm 需要按同一套约束重算底座宽度，不是简单缩放。"}],transfer:["平板阅读支架","显示器增高架","实验仪器斜面台"],course:{slug:"junior-3d-foundation",title:"3D 建模与打印基础"},articles:[{slug:"slicing-layer-infill-support",title:"切片课怎么讲：层高、填充和支撑的生活比喻"},{slug:"twenty-minute-visible-result",title:"二十分钟可见成果：第一次课堂打印怎么排"}]},{slug:"gear-teaching-kit",title:"齿轮传动教具",level:"进阶",type:"教具",hours:6,tag:"进阶 · 6 课时",image:"/media/gear-teaching.jpg",alt:"3D 打印齿轮传动教具，可见不同齿数的齿轮与手摇柄",copy:"用可转动的齿轮组把“齿数比”变成看得见的转速差，学生要自己算中心距、留齿隙，并测出误差。",meta:"建模重点：轴孔 / 配合 / 装配",dims:"180 × 120 × 25 mm",material:"PLA（齿轮）/ 亚克力轴",weight:"约 145 g",modelTime:"3 小时",printTime:"约 4 小时",background:"物理课上讲传动比，课本插图是静态的，学生对“齿数变了转速就变”没有体感。教师提出做一个能用手摇、能换齿轮的教具，要求一组齿轮在 30 秒内完成更换。",goal:"认识齿数比、中心距和装配间隙，用数据而不是手感评价机构是否合格。",constraints:["模数统一为 2，中心距按 m(z₁+z₂)/2 计算，误差不超过 ±0.15 mm","齿侧留 0.2 mm 齿隙，过小会卡死，过大会回差明显","轴孔 5.2 mm 配 5 mm 亚克力轴，手压装配不晃动","手摇 200 转不出现跳齿或明显温升","整套件可平铺打印，不需要支撑"],skills:["参数化建模","中心距计算","轴孔配合","装配验证"],steps:["确定三组齿数比（12:36、20:20、36:12）与统一模数","用参数表驱动齿数、模数，自动算出分度圆与中心距","建轴孔与限位台阶，孔口加 0.4 mm 倒角便于压入","把齿轮平面朝下摆放，检查齿顶是否在首层被压塌","分件打印后装配，测量啮合间隙并记录跳齿转速"],settingsRows:[["层高","0.16 mm","齿形轮廓在薄层下更接近理论曲线"],["墙线","3 圈","齿根受力集中，墙线不足会从齿根断"],["填充","25% 立方","齿轮以轮廓受力为主，过高填充收益有限"],["支撑","不使用","平面朝下摆放可完全避免支撑残留"],["打印顺序","先外后内","减少喷嘴跨越已成型齿面造成的拉丝"]],failures:["装上去转不动：中心距偏小或齿隙不足，先量中心距再改齿形","齿顶毛刺挂手：首层被压扁，需调高喷嘴或降低首层流量","轴孔松旷、齿轮摆动：孔口未倒角导致压入时刮料，实际配合变松"],iterations:[{round:"第 1 版",issue:"12:36 组在 30 转后卡死",change:"中心距 +0.15 mm，齿顶加 0.3 mm 倒角",evidence:"连续 200 转无卡死"},{round:"第 2 版",issue:"快速手摇时听到跳齿声",change:"齿宽 6 → 8 mm，轴孔加限位台阶抑制偏摆",evidence:"120 rpm 下无跳齿"}],tests:[{item:"传动比误差",method:"输入手摇 10 转，数输出转数",target:"与理论值偏差 < 3%",actual:"12:36 组偏差 1.7%"},{item:"连续运转",method:"手摇 200 转",target:"无跳齿、无卡死",actual:"通过"},{item:"装配间隙",method:"塞尺 + 目视啮合印痕",target:"0.15–0.25 mm",actual:"0.2 mm"},{item:"更换耗时",method:"从拆下到装回并转动",target:"≤ 30 秒",actual:"22 秒"}],defend:[{q:"为什么不直接买现成的齿轮组？",a:"现成齿轮组的齿数是固定的，学生看不到“改一个参数、传动比就变”的过程，而这是我们这节课的核心。"},{q:"打印齿轮的强度够吗？",a:"教学场景是手摇、低扭矩，够用。如果要做动力输出，需要换 PETG 或尼龙并加大模数。"},{q:"误差 1.7% 从哪来？",a:"主要来自齿隙和轴孔配合，其次是层高造成的齿形近似，不是建模算错。"}],transfer:["凸轮机构演示","连杆与曲柄","简易机械臂关节"],course:{slug:"senior-3d-engineering",title:"三维设计与工程创新"},articles:[{slug:"ai-mesh-detail-still-needs-wall-thickness",title:"AI 网格把细节分辨率再往上推，课堂仍要先量壁厚"},{slug:"student-modeling-software",title:"学生建模软件怎么选：课堂工具，而不是品牌绑定"}]},{slug:"cable-organizer",title:"桌面线缆整理器",level:"简单",type:"功能",hours:2,tag:"简单 · 2 课时",image:"/media/cable-organizer.jpg",alt:"3D 打印桌面线缆整理夹，夹住不同粗细的充电线",copy:"从教室充电车线缆缠绕的问题出发，用三种开口宽度做对照样件，用卡入力决定最终方案。",meta:"建模重点：卡扣 / 公差 / 使用测试",dims:"68 × 34 × 18 mm",material:"PETG（韧性更好）",weight:"约 12 g",modelTime:"60 分钟",printTime:"约 45 分钟",background:"充电车里 30 根线每天缠成一团，学生想到的方案不是“做个盒子”，而是“让每根线有自己的位置”。这个任务的关键不是造型，而是开口多大才既能卡住又不勒坏线。",goal:"将“好用”拆成线径范围、卡入力和重复使用次数三个可测指标。",constraints:["兼容 3–6 mm 线径，覆盖常见充电线与数据线","卡入力控制在 5–15 N，过紧会压伤线皮","同一开口重复卡入 30 次后不得明显松弛","底部留 20 × 20 mm 平面，可用双面胶固定","单件耗材不超过 15 g，一间教室 30 个的总成本可控"],skills:["线径测量","弹性卡扣","圆角设计","对照实验"],steps:["抽样测量 10 根线缆外径，记录最小、最大与中位数","设计三种开口宽度：线径 −0.4 mm、线径、线径 +0.4 mm","开口入口做 30° 导角，内侧加 R1.6 圆角防止撕裂","底部加 0.6 mm 薄裙边增加粘贴面积","三个样件一起打印，逐个记录卡入力与保持效果"],settingsRows:[["层高","0.2 mm","薄壁件不必追高精度，时间优先"],["墙线","3 圈","卡扣靠墙线弹性变形，2 圈易断"],["填充","20%","主要受力在开口两侧，填充影响小于墙线"],["材料","PETG","韧性优于 PLA，反复卡入不易脆裂"],["摆放方向","开口朝上","避免开口内侧出现支撑残留"]],failures:["第一次卡入就裂：开口内侧是直角，或用了脆性 PLA","卡不住细线：开口按最粗线径设计，细线直接被放过","粘不住桌面：底面太小或有拔模斜度，胶接触面积不足"],iterations:[{round:"第 1 版",issue:"6 mm 开口卡入 5.6 mm 线时开裂",change:"内侧圆角 R0.8 → R1.6，材料改 PETG",evidence:"同尺寸卡入 30 次无裂纹"},{round:"第 2 版",issue:"3.5 mm 细线在开口里晃动",change:"增加一档 3.1 mm 规格，按线径分三档",evidence:"三档各自适配，无晃动"}],tests:[{item:"卡入力",method:"弹簧秤拉线通过开口",target:"5–15 N",actual:"5.6 mm 线为 9 N"},{item:"保持力",method:"挂 200 g 砝码静置 1 分钟",target:"不下滑",actual:"不下滑"},{item:"重复使用",method:"同一开口卡入 30 次",target:"无裂纹、无松弛",actual:"通过"},{item:"单件重量",method:"电子秤",target:"≤ 15 g",actual:"12 g"}],defend:[{q:"为什么不做成一整块理线板？",a:"整块板只能适配一种线径，教室里线径差异很大；模块化可以按需要拼。"},{q:"PETG 打印有什么代价？",a:"容易拉丝、首层附着更难，需要降速并调好间距，课堂要多留 10 分钟清理。"},{q:"怎么证明它比原来好用？",a:"我们用“取一根线的时间”和“缠绕次数”两个指标做了前后对照，不是凭感觉。"}],transfer:["工具挂架","笔夹与卡片夹","充电车分区收纳"],course:{slug:"junior-3d-foundation",title:"3D 建模与打印基础"},articles:[{slug:"filament-moisture-and-classroom-storage",title:"耗材受潮会拉丝、会分层：教室里先管干燥，再谈新材料"},{slug:"slicing-layer-infill-support",title:"切片课怎么讲：层高、填充和支撑的生活比喻"}]},{slug:"bridge-structure",title:"桥梁承重结构",level:"项目",type:"结构",hours:8,tag:"项目 · 8 课时",image:"/media/bridge-structure.jpg",alt:"学生给 3D 打印桁架桥模型逐级加配重做承重测试，桌上摊着受力设计图",copy:"在统一跨度、统一总重的条件下比较桁架、拱与梁三种方案，逐级加载到破坏并记录失效位置。",meta:"建模重点：结构 / 肋板 / 测试",dims:"跨度 240 mm，总重 ≤ 90 g",material:"PLA",weight:"单件 78–88 g",modelTime:"4 小时",printTime:"约 6 小时",background:"校园里一处人行连廊需要临时坡道，学生提出“先做模型比方案”。教师把任务改成受限设计：同样跨度、同样总重，谁的承载效率高，谁进下一轮。这就把美术作业变成了工程比较。",goal:"用相同材料和跨度比较桁架、拱和梁的承重表现，建立可重复的测试记录。",constraints:["净跨度固定 240 mm，两端支承面各 20 mm","单件总重不超过 90 g，超出即失去比较意义","统一打印方向与填充，排除工艺差异","加载点在跨中，按 5 N 一级逐级加载，每级停留 10 秒","承重测试必须教师在场，配重下方不得站人"],skills:["结构受力","三角稳定","截面设计","数据记录"],steps:["确定跨度、总重上限与加载方式，写出比较规则","分别设计桁架、拱、梁三种方案，保持材料用量接近","统一 0.2 mm 层高、30% 填充与摆放方向，一次排产","逐级加载，记录每级位移，破坏后拍照标注失效位置","用“承载力 / 自重”计算效率，画出三方案对比图"],settingsRows:[["层高","0.2 mm","三种方案必须一致，否则比较无效"],["墙线","3 圈","杆件以轴力为主，墙线决定节点强度"],["填充","30% 立方","节点区域可局部加密，整体保持一致"],["摆放方向","整体平放","层向垂直于主要弯矩，避免层间剥离"],["支撑","仅拱方案需要","支撑位置需在报告中说明，避免影响结论"]],failures:["加载第一级就断：节点截面过小，应力集中","三种方案数据不可比：打印方向或填充不一致","破坏位置每次不同：加载点没有固定，配重偏心"],iterations:[{round:"第 1 版",issue:"桁架在 180 N 时下弦节点断裂",change:"节点加腋，下弦截面 8 → 12 mm²",evidence:"同条件复测 312 N"},{round:"第 2 版",issue:"拱方案侧向失稳，非强度破坏",change:"增加横向系杆，限制侧移",evidence:"破坏模式变为跨中压溃"}],tests:[{item:"桁架承载力",method:"跨中逐级加载 5 N/级",target:"记录到破坏",actual:"312 N 下弦节点断裂"},{item:"拱承载力",method:"同上",target:"记录到破坏",actual:"268 N 跨中压溃"},{item:"梁承载力",method:"同上",target:"记录到破坏",actual:"154 N 跨中受拉侧断裂"},{item:"承载效率",method:"承载力 ÷ 自重",target:"三方案对比",actual:"桁架 3.8、拱 3.1、梁 2.0"}],defend:[{q:"为什么桁架赢？",a:"桁架把弯矩转成杆件轴力，材料主要受拉压而不是受弯，同样重量下效率更高。"},{q:"这个数据能直接用于真实桥梁吗？",a:"不能。模型是等比缩小、材料均质，真实结构还要考虑连接、疲劳、风载与安全系数。"},{q:"如果总重再减 20 g，你会改哪里？",a:"先减非受力腹杆截面，再把节点从实心改成镂空，但要重新验证节点强度。"}],transfer:["承重支架","塔架结构","包装缓冲结构"],course:{slug:"senior-3d-engineering",title:"三维设计与工程创新"},articles:[{slug:"factory-tooling-not-just-gadgets",title:"工厂把打印用在夹具上：学生项目也可以先问「这件东西要干活吗」"},{slug:"classroom-safety-three-rules",title:"课堂安全三原则：不碰喷头、不伸手、不改材料"}]},{slug:"robot-connector",title:"机器人连接件",level:"进阶",type:"机器人",hours:6,tag:"进阶 · 6 课时",image:"/media/robot-connectors.jpg",alt:"3D 打印机器人结构连接件，带螺丝孔位与快拆结构",copy:"围绕安装空间和孔位做可替换连接件，练基准、公差与可维护性，装配一次就能看出误差在哪。",meta:"建模重点：基准 / 配合 / 装配",dims:"74 × 46 × 22 mm",material:"PETG",weight:"约 38 g",modelTime:"3 小时",printTime:"约 3 小时",background:"机器人社团的机械臂每次更换末端执行器都要重新打孔，孔位越打越偏。学生提出做一套统一接口的连接件，让末端件可以像积木一样换。这个任务第一次让“基准”这个词变得具体。",goal:"理解基准面、孔位、公差和可维护性，完成一次真实装配验证。",constraints:["孔位相对基准面的位置度误差不超过 ±0.15 mm","M3 螺丝配热熔铜螺母，孔壁厚不小于 2 mm","快拆结构需在 10 秒内完成拆装，且有防呆方向","层向不得与主受力方向平行，避免层间开裂","单件打印不超过 3 小时，社团一次活动能出两件"],skills:["基准建立","孔位阵列","热熔螺母","快拆设计"],steps:["测量机械臂安装面，确定一个主基准面与两个定位孔","以基准面为原点建立孔位阵列，标注公差","设计热熔铜螺母孔（外径 4.6 mm，深 5.5 mm）与导入倒角","加防呆凸台，确保只能一个方向装入","打印后热压螺母、装配、记录干涉与松紧"],settingsRows:[["层高","0.16 mm","孔位圆度更好，热熔螺母不易偏"],["墙线","4 圈","螺母孔周边需要足够壁厚承力"],["填充","30% 立方","连接件以局部承压为主，节点需加密"],["材料","PETG","韧性好，热熔螺母时不易开裂"],["摆放方向","孔轴平行于平台","避免层间被螺丝撑开"]],failures:["螺丝拧紧后孔壁开裂：层向与孔轴垂直，或壁厚不足 2 mm","装上去歪 1 mm：孔位不是从同一基准阵列出来的","热熔螺母歪斜：孔径过大或没有导入倒角"],iterations:[{round:"第 1 版",issue:"M3 螺丝拧到 0.8 N·m 时孔壁出现裂纹",change:"旋转摆放方向使孔轴平行平台，壁厚 1.6 → 2.4 mm",evidence:"1.2 N·m 无裂纹"},{round:"第 2 版",issue:"快拆件装反后卡死",change:"增加 2 mm 防呆凸台与非对称导向槽",evidence:"反向无法装入"}],tests:[{item:"孔位精度",method:"装配后塞尺与影像测量",target:"±0.15 mm",actual:"±0.1 mm"},{item:"螺纹承力",method:"扭矩扳手逐级加扭",target:"≥ 1.0 N·m 不裂",actual:"1.2 N·m"},{item:"拆装寿命",method:"同一接口反复拆装",target:"50 次不松",actual:"50 次后扭矩衰减 8%"},{item:"快拆耗时",method:"计时拆装各一次",target:"≤ 10 秒",actual:"7 秒"}],defend:[{q:"为什么不直接用铝件？",a:"社团阶段迭代快，铝件加工周期和成本都高；打印件当天就能改，等结构稳定后再考虑金属。"},{q:"热熔螺母会不会被拉出？",a:"按 4.6 mm 外径、5.5 mm 深度压入后，拉脱力明显高于螺丝预紧力；关键是壁厚和导入倒角。"},{q:"精度 ±0.1 mm 怎么保证的？",a:"一是所有孔从同一基准阵列，二是孔轴平行平台摆放，三是热熔时用台钳限位。"}],transfer:["传感器支架","末端执行器快换","竞赛机器人的减重结构件"],course:{slug:"senior-maker-challenge",title:"科创竞赛项目营"},articles:[{slug:"model-marketplace-and-student-original-work",title:"模型市场越来越好用，课堂作业仍要学生自己完成结构"},{slug:"ai-mesh-detail-still-needs-wall-thickness",title:"AI 网格把细节分辨率再往上推，课堂仍要先量壁厚"}]}],process:[{title:"首层测试片",image:"/media/first-layer.jpg",kicker:"Layer 01",look:"看线条是否被压扁、线与线之间是否留有缝隙、四角是否翘起。",why:"首层决定附着与尺寸基准。首层没调好，后面的尺寸测量全部不可信。",record:["喷嘴与平台间距","平台清洁方式","首层实际厚度（卡尺）"],note:"课堂做法：每换一卷耗材先打一片 40 × 40 mm 单层片，通过后再排产学生作品。"},{title:"失败件复盘",image:"/media/failed-print-review.jpg",kicker:"Evidence 02",look:"看断口是层间剥离还是丝材断裂，看失败发生在第几层。",why:"失败件是最便宜的证据。能说清失败原因，比多做三个成功件更有价值。",record:["失败层高与时间点","当时设备参数","原因假设与下次改动"],note:"我们不建议把失败件丢掉：贴标签归档，答辩时它往往是最有说服力的材料。"},{title:"切片参数对照",image:"/media/slicing-basics.jpg",kicker:"Evidence 03",look:"同一模型在 0.16 / 0.2 / 0.28 mm 层高下的时间、克重与外观差异。",why:"让学生看到“精度是用时间换的”，参数不是背下来的，是比出来的。",record:["预估时间 vs 实际时间","克重","外观与强度主观评分"],note:"一张对照表就能解释为什么课堂作业默认 0.2 mm，而不是越细越好。"},{title:"首件成品验证",image:"/media/first-print.jpg",kicker:"Evidence 04",look:"成品与设计尺寸的差值、装配是否一次通过、表面是否需要后处理。",why:"从数字模型到实物，中间隔着补偿量。首件必须量，不能只看像不像。",record:["关键尺寸实测值","与设计值偏差","装配结果"],note:"首件合格标准由学生自己写进任务单，教师只审核标准是否可测。"}],scoring:[{dim:"功能达成",weight:"30%",evidence:"针对提出的问题给出可复现的测试数据",bad:"只有成品照片，没有测试过程"},{dim:"结构与工艺",weight:"25%",evidence:"壁厚、层向、公差、支撑位置有明确理由",bad:"参数照抄，问为什么答不出"},{dim:"过程证据",weight:"20%",evidence:"草图、版本记录、失败件与改版说明齐全",bad:"只有最终版文件"},{dim:"表达与答辩",weight:"15%",evidence:"三分钟讲清问题、方案、证据与下一步",bad:"只描述外观，不回答问题"},{dim:"安全与规范",weight:"10%",evidence:"设备操作、材料管理、场地清理符合课堂要求",bad:"无人值守打印、工具乱放"}],collections:[{slug:"classroom-starter",title:"课堂六件起步包",level:"简单 → 项目",intro:"一个学期从薄板件走到结构测试的六个任务，每件都有明确的验收标准与可复现参数。",items:["校园文创徽章","桌面线缆整理器","手机支架","齿轮传动教具","机器人连接件","桥梁承重结构"],forWho:"初次开设 3D 打印课的班级",duration:"约 24 课时"},{slug:"desk-system",title:"桌面收纳系统",level:"简单",intro:"以“桌面动线”为主线，把线缆、笔、卡片、工具分区，练尺寸测量与模块拼接。",items:["线缆整理夹","笔槽模块","卡片立架","工具挂板"],forWho:"初一、初二入门班",duration:"约 8 课时"},{slug:"structure-lab",title:"结构测试合集",level:"项目",intro:"同一套加载方法，比较桁架、拱、梁与薄壳四种结构的承载效率。",items:["桁架桥","拱桥","梁式桥","薄壳穹顶"],forWho:"高一、高二工程方向",duration:"约 12 课时"},{slug:"subject-models",title:"学科教具合集",level:"普通 → 进阶",intro:"把地理、生物、物理里“讲不清”的部分做成可拆装模型，重点在比例与标注。",items:["等高线地形块","细胞结构分层件","齿轮传动组","太阳高度角演示架"],forWho:"学科融合课与教研组",duration:"按学科定制"},{slug:"campus-culture",title:"校园文创合集",level:"简单",intro:"徽章、班牌、纪念章与展台小件，练文字、薄板与多色装配，适合活动周期短的项目。",items:["社团徽章","班级门牌","活动纪念章","展台托架"],forWho:"社团、德育活动、开放日",duration:"约 6 课时"}],cases:[{slug:"school-curriculum",title:"一学期，把建模课变成校园展",industry:"教育 · 校本课程",scale:"初中 7–8 年级 · 6 个班",cover:"/img/news/case-edu.jpg",challenge:"学校已有设备但课程零散，学生每节课做一个小件，学期末拿不出可展示的成果。",constraints:["每周 1 课时，不能占用其他学科","两位任课教师都非工科背景","设备 6 台，需轮转排产"],approach:["把学期拆成“技能周 + 项目周”：前 8 周每课一个可验收小件，后 6 周进入项目","每件作品配一张任务单，写明验收标准由谁测、怎么测","建立作品档案：草图、版本文件、失败件照片、答辩录音各一份","学期末用一面墙做展，作品旁必须挂过程记录，不挂奖状"],metrics:[{label:"可展示作品",value:"168 件",note:"6 个班全员完成"},{label:"一次出件率",value:"86%",note:"首件无需返工"},{label:"教师独立授课",value:"第 5 周起",note:"不再需要外聘讲师在场"}],risks:"设备故障会打乱排产，建议保留 1 台备用机并提前切片排程。",transfer:"适合已有设备、缺课纲与评价体系的学校。"},{slug:"subject-teaching-aids",title:"把讲不清的知识点做成可拆装教具",industry:"教育 · 学科教具",scale:"地理 / 生物教研组 · 4 个课题",cover:"/img/education/gen-cad-modeling.jpg",challenge:"等高线、细胞结构、太阳高度角这些内容，挂图和动画都不如手里能拆的模型。",constraints:["教具需在 40 人班级中反复使用","单件重量不超过 1.2 kg","标注文字必须可替换"],approach:["先由学科教师写“讲不清的三句话”，再由学生翻译成结构需求","采用分层插接结构，关键层用异色耗材区分","标注做成可插拔小牌，避免不同教材版本导致教具报废","每件教具附一张“课堂用法卡”，写明提问顺序"],metrics:[{label:"教具件数",value:"11 件",note:"覆盖 4 个课题"},{label:"单件打印",value:"3.5–9 小时",note:"分批排产"},{label:"课堂复用",value:"一学期 20 次以上",note:"无结构失效"}],risks:"教具不是越精细越好，标注过多会让学生在课堂上抓不住重点。",transfer:"适合教研组做跨学科项目，也适合作为学生项目选题来源。"},{slug:"industrial-fixture",title:"小批量检测工装：先做对，再做快",industry:"工业 · 工装夹具",scale:"电子装配 · 单批 200–500 件",cover:"/img/news/case-industry.jpg",challenge:"产线小批量多品种，金属工装开模周期长，换型一次要等两周。",constraints:["换型时间需压到 1 天内","定位精度 ±0.2 mm","工装需承受每日 300 次取放"],approach:["用打印件做定位与支撑，受力最大的压紧块仍用金属","定位面留 0.2 mm 补偿量，首件实测后修正模型","每个品种一套色标，避免混用","建立换型清单：模型版本、打印参数、首件检测项"],metrics:[{label:"换型周期",value:"2 周 → 1 天",note:"设计到可用工装"},{label:"定位偏差",value:"±0.15 mm",note:"首件三坐标抽检"},{label:"工装寿命",value:"约 3000 次",note:"易损件可单独更换"}],risks:"打印件蠕变会随载荷与温度累积，承力部位不能全靠塑料。",transfer:"适合多品种小批量、换型频繁的装配与检测场景。"},{slug:"medical-aid",title:"康复辅具的尺寸验证件",industry:"医疗 · 辅具适配",scale:"康复科 · 单例定制",cover:"/img/news/case-medical.jpg",challenge:"辅具定制依赖手工取样，试戴不合适就要重做，周期长、浪费材料。",constraints:["打印件不得直接接触破损皮肤","仅用于尺寸与形态验证","材料需可清洁、无刺激性气味"],approach:["先用低密度打印件做形态验证，确认贴合与活动范围","验证通过后再由具备资质的机构制作最终辅具","每例保留验证件的尺寸记录，作为下一例的参考","明确边界：打印件不是医疗器械，不进入临床使用"],metrics:[{label:"试戴轮次",value:"3 次 → 1–2 次",note:"形态验证前置"},{label:"单例验证件",value:"40–90 g",note:"低填充快速件"},{label:"验证周期",value:"约 2 天",note:"含打印与试戴"}],risks:"必须由专业人员判断适配性；打印件不能宣称医疗功效或替代医疗器械。",transfer:"适合需要反复试形的定制件，如护具、握把、坐垫外形验证。"},{slug:"culture-goods",title:"景区文创的短版生产",industry:"文创 · 小批量",scale:"单款 50–300 件",cover:"/img/education/gen-multicolor-parts.jpg",challenge:"文创首单不敢压库存，传统开模起订量高，卖不动就全砸在仓库。",constraints:["单款起订 50 件以内","交期 7 天","表面需可后处理上色"],approach:["主体统一，图案与文字做成可替换嵌件","按 50 件一批排产，卖完再补，避免库存","统一后处理流程：打磨、底漆、手绘、面漆","为每款保留模型版本号，返单时直接复用"],metrics:[{label:"起订量",value:"50 件",note:"约为开模方案的 1/10"},{label:"交期",value:"7 天",note:"含后处理"},{label:"单件成本",value:"高于量产、低于开模试错",note:"按批量浮动"}],risks:"打印件耐候性弱于注塑件，户外长期使用需选材并做涂层验证。",transfer:"适合验证市场反应、展会样品、限量联名款。"},{slug:"competition-iteration",title:"竞赛机器人的结构件快迭代",industry:"竞赛 · 结构件",scale:"校队 · 8 周备赛",cover:"/img/competition/robotics-arena.jpg",challenge:"备赛期结构改动频繁，外协加工一次三天，改到第五版已经来不及验证。",constraints:["单件必须当天出、当天装","孔位需与现成铝型材兼容","比赛现场可快速更换"],approach:["建立统一接口：孔距、螺母规格、基准面全部固定","易损件做成快换模块，赛场 10 秒更换","每版结构标版本号，装配图与打印文件同号","备件按 1:2 打印（一件装机、一件备用）"],metrics:[{label:"迭代周期",value:"3 天 → 6 小时",note:"设计到装机"},{label:"赛场更换",value:"约 10 秒",note:"快换模块"},{label:"备件覆盖率",value:"关键件 1:2",note:"按失效概率分级"}],risks:"打印件刚度低于金属，高频振动部位需加厚或改金属；部分赛项限定器材，须逐项核对规则。",transfer:"适合任何需要当天验证结构假设的场景。"}],solutions:[{slug:"education",kicker:"SOLUTION · EDUCATION",title:"教育与 STEAM：让每个课时都能出件",lead:'学校不缺设备，缺的是"每周一课时也能稳定出件"的课纲、验收标准和排产方式。这一页写清三件事：谁来教、怎么排产、作品怎么被评价。',stats:[["86","%","一次出件率（6 个班）"],["168","件","一学期可展示作品"],["11","件","学科教具，覆盖 4 个课题"],["1","学期","从零到校园展的周期"]],fit:{kicker:"Who it fits",title:"四种情况，先定流程",lead:"设备可以买，流程买不到。先看自己卡在哪一步，再决定先补课纲还是先补排产。",items:[{tag:"已有设备",title:"课程零散，学期末拿不出成果",body:"每节课做一个小件，作品散落在学生手里，没有过程记录，也拼不成一场展。需要一条从技能周走到项目周的学期主线。"},{tag:"学科教师",title:"想把模型用进学科难点",body:"等高线、细胞结构、传动比这类内容，讲十遍不如让学生手里拆一次。教具由教研组提需求，学生做结构。"},{tag:"非工科背景",title:"任课教师不是工科出身",body:"课纲要能照着上。任务单、验收标准、失败排查表都要写死在纸面上，而不是依赖外聘讲师的经验。"},{tag:"排产压力",title:"班多机少，打印排队",body:"6 台设备、6 个班时，排产本身就是课程设计的一部分：谁先打、打多久、坏了怎么补。"}]},build:{kicker:"How it is built",title:"一套课，由四块拼成",lead:'课纲、设备、材料、评价，四块任何一块缺位，学期末就会退回"每节课做个小玩意"的状态。',items:[{kicker:"Block 01 / 课纲",title:"技能周 + 项目周",body:"前 8 周每课一个可验收小件，后 6 周进入完整项目。小件不是为了好看，是为了把壁厚、公差、支撑这些动作练成肌肉记忆。",list:["8 周技能周：每周一个可验收小件","6 周项目周：一件作品走完约束—改版—测试","每件作品一张任务单，写明验收标准由谁测"]},{kicker:"Block 02 / 设备",title:"按台数轮转，不按班号排队",body:"6 台设备对应 6 个小组，轮转周期固定，避免某个班长期占用。留 1 台备用机应对堵料与故障。",list:["单件打印控制在 35–90 分钟","每台设备一张排产卡，标注切片文件版本","保留 1 台备用机，故障时不影响整班"]},{kicker:"Block 03 / 材料",title:"课堂只用两种材料起步",body:"PLA 出件快、气味小，作为默认材料；PETG 到第二学期再引入。材料换得越少，参数越稳定，故障排查越快。",list:["PLA：薄板件、教具、外观件","PETG：卡扣、连接件，需降速","同一学期不混用超过两种耗材"]},{kicker:"Block 04 / 评价",title:"五维量表，每个维度都要证据",body:"成品外观只占一小部分。功能、结构、证据、表达、安全各有权重，每一项都要拿得出对应材料。",list:["功能 30 / 结构 25 / 证据 20 / 表达 15 / 安全 10","失败件必须保留，并写清失败位置","答辩固定三问：为什么、数据说明什么、下一步改哪"]}]},steps:{kicker:"Rollout",title:"落地五步，按学期排",lead:"顺序不要颠倒。先定课时再定项目规模，先写验收标准再选模型。",items:[{title:"Step 01 · 定学段与课时",body:"先确认每周几课时、几周、几个班。课时决定项目规模，不是反过来。"},{title:"Step 02 · 写验收标准",body:"每条标准都要可测：尺寸、承重、装配次数。写不出测法的标准，直接删掉。"},{title:"Step 03 · 选起步模型",body:"从作品展厅挑 6 件难度递进的模型，先让任课教师自己完整做一遍。"},{title:"Step 04 · 排产与轮转",body:"按设备台数排切片，同一时段不超过两种耗材，切片提前一周完成。"},{title:"Step 05 · 学期展与答辩",body:"作品旁挂过程记录，不挂奖状。答辩看的是改版理由，不是成品漂不漂亮。"}]},params:{kicker:"Print settings",title:"课堂默认参数",lead:"这是全班共用的起点值，不是唯一正确答案。换设备、换耗材、换教室温度，都要重新打测试片。",head:["参数","课堂起点值","为什么这样设"],rows:[["层高","0.2 mm","出件速度与表面质量的平衡点；0.12 mm 留给展示件"],["墙数 / 壁厚","3 层，约 1.2 mm","薄于此值，卡扣与螺孔容易开裂"],["填充","15 %（网格）","教具需承力时提到 25–30 %"],["外壁速度","40–60 mm/s","超过 80 mm/s 时，小件转角容易出振纹"],["热床 / 喷嘴","60 ℃ / 205 ℃（PLA）","首层附着最稳的一组起始值"],["支撑","仅接触面，优先改结构避开","课桌上拆支撑最容易划伤学生手"]],note:"以上为课堂默认起点，随设备型号、耗材品牌与教室温度变化。换料必须先打测试片，不要直接排产全班。"},fails:{kicker:"Failure modes",title:"三类最常见的翻车",lead:"这三类问题占了课堂故障的大半。提前写进排查表，学生自己就能处理。",items:[{title:"首层不粘，整班连环失败",body:"教室空调直吹、热床未校准、平台有油。",fix:"开课前 10 分钟统一预热并打第一层；平台用酒精擦一遍；风口避开设备。"},{title:"文字与细杆打印中断裂",body:"笔画宽度小于 0.8 mm，或细杆长径比过大。",fix:"文字做凸起 0.6 mm 以上并加圆角；细杆改扁或加斜撑。"},{title:"排产挤在同一节课",body:"所有小组同时切片，打印队列堵死。",fix:"切片提前一周完成，按 30 分钟一档错峰开打。"}]},caseSlugs:["school-curriculum","subject-teaching-aids"],workSlugs:["gear-teaching-kit","bridge-structure","robot-connector"],workNote:"三件课堂练习分别覆盖教具、结构与接口三类典型任务，每件都有完整档案与打印参数。",boundary:"本页与相关案例中的数字为教学与打样记录口径，不构成对教学效果、评奖结果或设备性能的承诺。课程按学校实际课时、班级规模与设备条件重排。",cta:{title:"把课时表发给我们，换一份排产方案",lead:"给出学段、周课时、班级数与设备台数，我们按学期把课纲拆到周。",primary:["/solutions/school.html","学校合作方案"],secondary:["/trial.html","预约试听"]},next:[["/courses/index.html","课程中心","按学段与课时查看完整课程大纲"],["/works.html","作品展厅","十份作品与过程档案，可直接当选题"],["/teachers.html","师资教研","教师培训与教研支持方式"],["/explore/collections.html","主题合集","按一条线索组一批作品，直接排课"]]},{slug:"creative",kicker:"SOLUTION · CULTURE & CONSUMER",title:"文创与消费品：先小批验证，再谈量产",lead:"首单不敢压库存，开模起订量又高。做法是把主体与图案拆开：主体统一、图案可替换，先做 50 件试水，卖完再补。",stats:[["50","件","单款最小起订"],["7","天","含后处理的交期"],["4","道","后处理工序"],["1/10","","起订量约为开模方案"]],fit:{kicker:"Who it fits",title:"四种典型场景",lead:"共同点是：数量不大、变化频繁、需要先拿到实物再决定下一步。",items:[{tag:"首单试水",title:"不确定卖不卖得动",body:"景区、博物馆与品牌周边的首单最怕压货。打印的起订量可以低到 50 件，卖完再补。"},{tag:"潮玩与手办",title:"开模前先验证结构",body:"分件、插接、重心、支撑位置，先打印验证，再去谈模具，能省掉一整轮改模。"},{tag:"展会样品",title:"一周内要拿到手上",body:"展会与提案需要实物。打印是少数能在一周内交付少量高细节实物的路径。"},{tag:"限量联名",title:"数量少但要质感",body:"后处理决定质感，打印只负责形体。打磨、底漆、手绘、面漆四道工序，缺一道就露馅。"}]},build:{kicker:"How it is built",title:"把可变的部分拆出来",lead:"能统一的统一，能替换的替换。分件不是为了炫技，是为了改文案时不用重做整套。",items:[{kicker:"Block 01 / 分件",title:"主体统一，图案做嵌件",body:"底板与主体一次成型，文字与图案做成可替换嵌件。改文案不用重做整套，坏一个补一个。",list:["嵌件与主体留 0.15–0.25 mm 配合间隙","嵌件背面做定位槽，避免装反","按颜色分件，减少中途换料"]},{kicker:"Block 02 / 表面",title:"后处理决定卖相",body:"打印层纹在侧光下最明显。打磨—底漆—手绘—面漆四道工序，缺一道就露馅。",list:["240 → 600 目逐级打磨","底漆薄喷两遍，间隔 15 分钟","面漆选哑光，掩盖残余层纹"]},{kicker:"Block 03 / 色彩",title:"色彩靠分件与耗材",body:"同一色号不同批次会有色差，一次排产要把同色件集中打完，渐变件不要靠喷涂现调。",list:["同色件集中排产","渐变件用分段耗材，不靠后期喷涂","浅色件避免与深色件同炉"]},{kicker:"Block 04 / 版本",title:"每款留版本号，返单直接复用",body:"返单最容易出问题的不是设计，是找不到当初那份文件和那组参数。",list:["模型版本号与商品编码同号","记录当次切片参数与耗材批次","返单先打一件对照件再批量"]}]},steps:{kicker:"Rollout",title:"从 SKU 到返单的五步",lead:"先算成本再定价，先打样再排产。顺序错了，后面每一步都要返工。",items:[{title:"Step 01 · 定 SKU 与售价带",body:"先算清单件耗时与后处理工时，再定价。打印成本高于量产，靠小批量与溢价支撑。"},{title:"Step 02 · 拆主体与嵌件",body:"能统一的统一，能替换的替换。分件越多，装配工时越高。"},{title:"Step 03 · 打样与手感确认",body:"重量、边角、开合手感都要上手确认，图片看不出这些。"},{title:"Step 04 · 小批排产",body:"按 50 件一批，同色集中打，留 5 % 损耗余量。"},{title:"Step 05 · 返单复用",body:"按版本号取文件与参数，先打对照件，确认一致后再批量。"}]},params:{kicker:"Print settings",title:"外观件的参数起点",lead:"外观件追表面，不追速度。同样的模型，降一半速度能换掉大半层纹。",head:["环节","起点值","说明"],rows:[["层高","0.16 mm","外观件的表面质量优先于出件速度"],["墙数 / 壁厚","3 层，不低于 1.2 mm","薄于此值，嵌件卡扣容易开裂"],["填充","15 %","摆件可降到 8 %，承力件提到 30 %"],["外壁速度","35–45 mm/s","降速换表面，外观件不要追速度"],["支撑","仅接触面 / 树状","接触面越小，后处理越省"],["后处理","打磨 → 底漆 → 手绘 → 面漆","每道之间留足干燥时间"]],note:"打印件的耐候性弱于注塑件。户外长期使用需选 ASA 或 PETG 并做涂层验证，不能直接沿用室内参数。"},fails:{kicker:"Failure modes",title:"三类最常见的翻车",lead:"外观件的问题大多出在表面与配合，而不是结构。",items:[{title:"层纹在侧光下明显",body:"层高偏大、外壁速度过快、耗材受潮。",fix:"外观件降到 0.12–0.16 mm，外壁 40 mm/s 以内，耗材先烘干。"},{title:"细杆与发丝状结构断裂",body:"长径比过大，且打印方向与受力方向垂直。",fix:"改变摆放方向让层线顺着受力；细杆加粗或改扁。"},{title:"嵌件装不进或晃动",body:"配合间隙按理论值给，没算打印收缩与首层扩展。",fix:"先打一组 0.1 / 0.15 / 0.2 / 0.25 mm 间隙的测试件，选定后再批量。"}]},caseSlugs:["culture-goods"],workSlugs:["campus-badge","phone-stand","cable-organizer"],workNote:"三件都是能卖的小件，档案里写了成本敏感点与两轮改版的理由。",boundary:"案例中的起订量、交期与成本区间为打样记录口径，随批量、工艺与后处理方式浮动，不构成报价或产能承诺。打印件不适合替代注塑件的长期户外使用。",cta:{title:"先做 50 件，再决定要不要开模",lead:"把 SKU 数量、尺寸与预期售价发给我们，我们先算一件的成本与工时。",primary:["/contact.html","提交 SKU 需求"],secondary:["/solutions/case.html?slug=culture-goods","看文创案例"]},next:[["/filament/materials.html","材料目录","外观件与承力件的选材差异"],["/works.html","作品展厅","小件的完整参数与改版记录"],["/products/selector.html","智能选型","按精度与幅面选设备"],["/solutions/case.html","案例库","六个场景的约束与做法"]]},{slug:"healthcare",kicker:"SOLUTION · MEDICAL & DENTAL",title:"医疗与齿科：只做形态与尺寸验证",lead:'打印件在这类场景里的角色是"看得见、摸得着的验证件"，用来减少试戴与沟通的往返次数。它不是医疗器械，也不进入临床使用。',stats:[["1–2","次","试戴轮次，原需 3 次"],["2","天","单例验证周期"],["40–90","g","单例验证件"],["0","项","临床用途声明"]],fit:{kicker:"Who it fits",title:"四种可以做的用途",lead:"边界很清楚：只做沟通、验证与教学，不做诊断，也不做进入人体的最终件。",items:[{tag:"术前沟通",title:"讲不清的解剖结构",body:"把影像数据转成实体模型，医患沟通与团队讨论从看图变成指物。模型只用于沟通，不用于诊断。"},{tag:"齿科工序",title:"模型与工序验证",body:"高细节模型用于形态确认与工序演练，最终修复体仍由具备资质的机构与设备完成。"},{tag:"辅具适配",title:"反复试戴、周期长",body:"先用低密度验证件确认贴合与活动范围，再交资质机构出最终件。试戴轮次可从 3 次压到 1–2 次。"},{tag:"教学培训",title:"需要可反复操作的实物",body:"教学模型强调可重复、可清洁、可替换，不追求临床精度，也不对应任何真实病例。"}]},build:{kicker:"How it is built",title:"验证件前置，最终件后置",lead:"打印件只承担试形这一步：确认贴合、活动范围与外观预期，然后把结论交给有资质的机构。",items:[{kicker:"Block 01 / 数据",title:"数据来源决定精度上限",body:"影像层厚与扫描分辨率决定模型能表达什么，后处理放大不了原始数据的精度。",list:["保留原始数据的层厚与设备信息","标注每个模型的用途：沟通 / 验证 / 教学","形态验证件不标注解剖尺寸公差"]},{kicker:"Block 02 / 材料",title:"可清洁、无刺激气味",body:"接触皮肤与黏膜的件一律不做。验证件优先选可清洁、气味低的材料，并明确一次性或可复用。",list:["不打印直接接触破损皮肤的件","材料需可清洁、无异味","光固化树脂按厂家要求清洗与后固化"]},{kicker:"Block 03 / 流程",title:"低密度快速件先行",body:"单例 40–90 g、约 2 天完成，只确认形态与贴合，不追表面质量。",list:["填充 8–10 %，快速验证","每次试戴记录日期、部位与修改点","每例保留尺寸记录，作为下一例参考"]},{kicker:"Block 04 / 边界",title:"哪些事我们不做",body:"不做诊断、不做治疗建议、不宣称医疗功效、不替代医疗器械，也不出具适配性结论。",list:["不提供进入临床的成品","不参与医疗决策","涉及专业判断时由具备资质的人员完成"]}]},steps:{kicker:"Rollout",title:"单例验证的五步",lead:"每一步都要留下书面记录。没有记录，下一例还要从零开始。",items:[{title:"Step 01 · 明确用途",body:"先写清这个件给谁看、用来干什么。用途决定精度与材料，不是反过来。"},{title:"Step 02 · 获取数据",body:"影像或扫描数据由具备资质的机构提供，我们不采集、不改写原始数据。"},{title:"Step 03 · 打验证件",body:"低密度快速件，优先确认形态与贴合，不追表面质量。"},{title:"Step 04 · 试戴与记录",body:"每次试戴记录日期、部位与修改点，形成可追溯的记录。"},{title:"Step 05 · 交资质机构",body:"验证通过后，最终件由具备相应资质的机构按医疗器械要求制作。"}]},params:{kicker:"Print settings",title:"验证件的参数起点",lead:"下表只说明打出验证件这一段。任何涉及人体的最终产品，其材料、灭菌、注册与生产资质都不在本页范围内。",head:["环节","起点值","说明"],rows:[["FDM 层高","0.12 mm","形态验证件；层纹不影响贴合判断"],["FDM 墙数 / 填充","2 层 / 8–10 %","快速验证，减重省时"],["光固化层厚","0.05 mm","高细节形态件与齿科模型"],["光固化后处理","清洗 + 二次固化","按树脂厂家参数执行，不可省略"],["材料","PLA / PETG / 405 nm 树脂","均不作为接触人体的最终件"],["交付边界","仅验证件","最终件由具备资质的机构制作"]],note:"上表为工艺说明，不构成材料或器械的适用性结论。涉及人体的产品需另行完成合规评估。"},fails:{kicker:"Failure modes",title:"三类最常见的问题",lead:"最严重的一类不是打印失败，而是用途越界。",items:[{title:"把验证件当成品用",body:"打印件在强度、耐清洁性与生物相容性上都不满足人体接触要求。",fix:'在文件、包装与沟通中标注"非医疗器械 · 仅用于形态验证"。'},{title:"尺寸偏差没有记录",body:"同一部位反复试戴，却说不清每次改了什么。",fix:"每例建一张记录卡：日期、部位、修改点、试戴结论。"},{title:"树脂后处理不彻底",body:"清洗不足或未二次固化，表面发粘、气味残留。",fix:"按厂家参数清洗与二次固化，操作时佩戴防护用具。"}]},caseSlugs:["medical-aid"],workSlugs:["bridge-structure","cable-organizer"],workNote:"医疗场景不做成品迁移。下列两项只作为尺寸精度与配合公差的课堂练习，不涉及任何人体应用。",boundary:"本页内容为工艺与流程说明，不构成医疗建议、诊断依据或器械宣称。任何进入临床或接触人体的产品，须由具备相应资质的机构按医疗器械法规完成。",cta:{title:"先确认用途，再谈精度",lead:"告诉我们这个件用于沟通、工序还是教学，我们给出对应的精度与材料建议。",primary:["/contact.html","提交应用需求"],secondary:["/solutions/case.html?slug=medical-aid","看辅具验证案例"]},next:[["/printers.html","设备对比","FDM 与光固化的精度与适用边界"],["/filament/materials.html","材料目录","树脂与线材的差异"],["/solutions/case.html","案例库","医疗辅具案例的约束与边界"],["/knowledge.html","知识中心","模型后处理与清洁流程"]]},{slug:"industrial",kicker:"SOLUTION · INDUSTRIAL",title:"工业原型：先做对，再做快",lead:"小批量多品种的产线，等的不是更快的机器，而是当天能换的工装和可复现的首件检测。",stats:[["1","天","换型周期，原需 2 周"],["±0.15","mm","首件定位偏差"],["3000","次","工装寿命，易损件可换"],["1:2","","关键件备件比"]],fit:{kicker:"Who it fits",title:"四种适合打印的工业件",lead:"判断标准只有一条：这个部位靠形状工作，还是靠强度工作。前者适合打印，后者不行。",items:[{tag:"工装夹具",title:"换型要等两周",body:"金属工装开模周期长。定位与支撑用打印件，受力最大的压紧块仍用金属。"},{tag:"替换零件",title:"停产件买不到",body:"非承力的外壳、护罩、把手、盖板，打印件可以顶上，而且能随时改。"},{tag:"装配检具",title:"靠卡尺一件件量",body:"把关键尺寸做成检具，一放就知道合不合格，比逐件测量快得多。"},{tag:"小批试制",title:"开模之前先验证",body:"20–200 件的小批试制，打印成本高于量产，但低于开模试错。"}]},build:{kicker:"How it is built",title:"塑料做形状，金属做力",lead:"打印件的优势是形状自由，短板是蠕变与疲劳。承力部位不能全靠塑料。",items:[{kicker:"Block 01 / 分工",title:"先分受力，再谈结构",body:"定位、支撑、导向用打印件；压紧、受冲击的部位用金属；易损件做成可单独更换的模块。",list:["定位 / 支撑 / 导向：打印件","压紧 / 受冲击：金属衬块","易损件独立成模块，单独更换"]},{kicker:"Block 02 / 定位",title:"留补偿量，靠首件修正",body:"打印收缩与装配间隙叠加后，理论尺寸往往差 0.1–0.3 mm。补偿量只能靠实测确定。",list:["定位面留 0.2 mm 补偿量","首件三坐标抽检后修正模型","每个品种一套色标，避免混用"]},{kicker:"Block 03 / 材料",title:"按载荷与温度选",body:"车间温度、油污、清洗剂都会影响寿命。PLA 耐温约 55 ℃，在产线环境里要慎用。",list:["PETG：卡扣、连接件，需韧性","PLA：常温、干燥环境的定位件","ABS / ASA：需耐温耐油时评估"]},{kicker:"Block 04 / 换型",title:"换型清单比模型更重要",body:"换一次型要动的是模型版本、切片参数与首件检测项，三样缺一不可。",list:["模型版本号与工装编号同号","切片参数存档，不靠记忆","首件检测项写进换型清单"]}]},steps:{kicker:"Rollout",title:"从工况到备件的五步",lead:"第一步做不实，后面全是重复打样。",items:[{title:"Step 01 · 写清受力与精度",body:"先标出哪些面定位、哪些面受力、公差多少。写不清就无法判断哪个部位能用塑料。"},{title:"Step 02 · 首件打样",body:"只打一件，装上去试。首件的价值是暴露问题，不是交付。"},{title:"Step 03 · 实测修正",body:"三坐标或塞尺实测，按偏差修正模型，再打第二件。"},{title:"Step 04 · 建换型清单",body:"把版本、参数、检测项写成一页纸，贴在工作台。"},{title:"Step 05 · 备件与寿命管理",body:"按失效概率分级备件，易损件 1:2，其余 1:1。"}]},params:{kicker:"Print settings",title:"工装件的参数起点",lead:"工装不追表面质量，追尺寸稳定与层间强度。",head:["参数","起点值","说明"],rows:[["层高","0.2 mm","表面让位于尺寸稳定与效率"],["墙数 / 壁厚","4 层，不低于 1.6 mm","承力件薄于此值转角易裂"],["填充","40 %（gyroid / cubic）","受冲击部位提到 60 % 或改金属"],["外壁速度","30 mm/s","降速换层间结合强度"],["材料","PETG / ABS","PLA 耐温约 55 ℃，产线环境慎用"],["后处理","退火（按材料）","可降内应力，但尺寸会二次变化，需重测"]],note:"打印件的蠕变会随载荷与温度累积。长期承力部位不能用打印件替代金属，任何精度结论以首件实测为准。"},fails:{kicker:"Failure modes",title:"三类最常见的翻车",lead:"工装的失效往往不是断，而是慢慢变形。",items:[{title:"两周后孔位变大、定位漂移",body:"蠕变累积，塑料在持续载荷下缓慢变形。",fix:"承力面改金属衬套，或降低预紧力并定期复检。"},{title:"首件合格，批量不合格",body:"换了耗材批次或环境温度，参数没跟着改。",fix:"同批工装用同一批耗材，换批先打对照件。"},{title:"承力件在冲击下断裂",body:"层间结合是弱面，受力方向与层线垂直。",fix:"调整摆放方向让层线顺着主受力方向；关键件改金属。"}]},caseSlugs:["industrial-fixture"],workSlugs:["cable-organizer","bridge-structure","robot-connector"],workNote:"三件课堂练习分别对应公差配合、受力结构与快换接口，是工装设计的基础动作。",boundary:"案例中的换型周期、定位偏差与寿命为打样与产线记录口径，随设备、材料与工况变化，不构成精度或寿命承诺。承力与安全相关部位须经工程判断并做验证。",cta:{title:"把工况写给我们，先算能不能打",lead:"给出载荷、温度、精度与批量，我们判断哪些件适合打印、哪些必须用金属。",primary:["/contact.html","提交工况需求"],secondary:["/solutions/case.html?slug=industrial-fixture","看工装案例"]},next:[["/printers.html","设备对比","幅面、精度与材料兼容性"],["/filament/materials.html","材料目录","PETG / ABS / ASA 的差异"],["/works.html","作品展厅","结构与配合类作品的完整参数"],["/support/ticket.html","提交工单","已有设备的故障与工艺问题"]]}]};
